  return title('YOUR PILOT, AT A GLANCE', 'Good work deserves good proof.', project.charter.customer || 'Your pilot workspace', `${btn('Edit charter', 'charter')}${add('evidence', 'Add evidence')}`) + demoBanner() + localDecisionNotice() + gateSummary() + `<div class="metric-grid">${metricCards}</div><div class="overview-columns"><div><section class="panel"><div class="panel-header"><div><h2 class="panel-title">The success criteria <span class="count-pill">${project.criteria.length}</span></h2><p class="panel-subtitle">The outcomes you agreed to. The reviews that make them count.</p></div><button class="text-button" data-action="navigate" data-page="criteria">View all ${icon('arrow')}</button></div>${previewCriteria.length ? previewCriteria.map((c) => `<div class="criteria-row"><span class="criterion-indicator ${currentCoverage(c.id)?.currentMet ? 'met' : 'unassessed'}" aria-hidden="true">${currentCoverage(c.id)?.currentMet ? '✓' : '!'}</span><div class="row-body"><h3 class="row-title">${esc(c.name)}</h3><p class="row-desc">${esc(c.threshold)}</p><div class="row-bottom"><span>${esc(c.owner)}</span><span class="row-date">${icon('link')}${project.evidence.filter((e) => e.criterionIds.includes(c.id)).length} evidence</span><span class="row-date">${icon('calendar')}${fmtDate(c.targetDate)}</span>${c.visibility === 'internal' ? pill('internal') : ''}</div></div><div class="row-side">${pill(c.status)}${freshnessPill(currentCoverage(c.id)?.freshness)}<button class="row-edit" aria-label="Edit ${esc(c.name)}" data-action="edit" data-section="criteria" data-id="${esc(c.id)}">↗</button></div></div>`).join('') : '<p class="no-results">Define the outcomes you want to prove.</p>'}<div class="panel-footer">Evidence informs the review. Only an explicit assessment changes the result.</div></section><div class="note-strip">${icon('shield')}<span><strong>A private workspace. A considered handover.</strong><br>New records and attachments start internal. Customer exports include only items you deliberately mark customer-visible.</span></div></div><div class="side-stack"><section class="readiness-card"><div class="readiness-head"><span class="section-kicker">HANDOVER READINESS</span>${icon('handover')}</div><h3>${readiness.ready ? 'Ready for a human review.' : 'A few things to resolve.'}</h3><p>${readiness.ready ? 'Automated workspace checks are clear. Review the customer preview and make the final handover decision.' : 'Keep the open questions visible. A clean handover starts with knowing what still needs a decision.'}</p><div class="readiness-line"><span>Workspace checks</span><strong>${readiness.warnings.length} review notes</strong></div><div class="readiness-line"><span>Checklist progress</span><strong>${done} of ${project.checklist.length} complete</strong></div>${btn(`Review handover ${icon('arrow')}`, 'navigate', '', 'data-page="handover"')}</section><section class="panel"><div class="panel-header"><h2 class="panel-title">Latest evidence</h2><button class="text-button" data-action="navigate" data-page="evidence">All ${icon('arrow')}</button></div><div class="mini-list">${[...project.evidence].sort((a, b) => b.collectedAt.localeCompare(a.collectedAt)).slice(0, 3).map((e) => `<div class="mini-item"><div class="mini-icon">${icon('file')}</div><div class="row-body"><h3 class="row-title">${esc(e.name)}</h3><p class="row-desc">${fmtDate(e.collectedAt)} · ${esc(e.owner)} ${isStale(e) ? '· stale' : ''}</p></div><button class="row-edit" aria-label="Edit ${esc(e.name)}" data-action="edit" data-section="evidence" data-id="${esc(e.id)}">↗</button></div>`).join('') || '<p class="no-results">Your evidence story starts here.</p>'}</div></section></div></div><div class="overview-bottom"><section class="panel"><div class="panel-header"><h2 class="panel-title">Keep an eye on</h2><button class="text-button" data-action="navigate" data-page="risks">Risks ${icon('arrow')}</button></div><ul class="warning-list">${readiness.warnings.slice(0, 3).map((w) => `<li><span class="warning-symbol" aria-hidden="true">!</span><span>${esc(w.message)}</span></li>`).join('') || '<li>No automated warnings. A local decision is not authenticated approval.</li>'}</ul></section><section class="panel"><div class="panel-header"><h2 class="panel-title">Decisions, not loose ends</h2><button class="text-button" data-action="navigate" data-page="decisions">Decision review ${icon('arrow')}</button></div><div class="mini-list">${decisionReviews.slice(-1).map((d) => `<div class="mini-item"><div class="mini-icon">${icon('decisions')}</div><div><h3 class="row-title">Recorded outcome: ${esc(d.outcome)}</h3><p class="row-desc">${esc(d.reviewer)} · ${fmtDate(d.date)}</p>${freshnessPill(d.freshness)}</div></div>`).join('') || '<p class="no-results">No explicit proceed, hold, or stop review yet. Historical notes are separate.</p>'}</div></section></div>`;
