function recordCard(section, r) {
  const meta = `<div class="record-meta">${pill(r.visibility)}<span>${esc(r.owner)}</span>${r.targetDate ? `<span>${fmtDate(r.targetDate)}</span>` : ''}${r.status ? pill(r.status) : ''}${r.severity ? pill(r.severity) : ''}${r.collectedAt ? `<span>Collected ${fmtDate(r.collectedAt)}</span>${isStale(r) ? pill('stale') : ''}` : ''}${r.date ? `<span>${fullDate(r.date)}</span>` : ''}${r.dueDate ? `<span class="${r.dueDate < day() && !r.done ? 'overdue' : ''}">Due ${fullDate(r.dueDate)}</span>${pill(r.done ? 'complete' : 'open')}` : ''}</div>`;
  let body = '';
  if (section === 'criteria') {
    const row = currentCoverage(r.id);
    body = details([['Metric', r.metric], ['Baseline', r.baseline], ['Success threshold', r.threshold]]) + `<div class="record-meta">${freshnessPill(row?.freshness)}${pill(row?.currentMet ? 'current' : 'changed', row?.currentMet ? 'Current gate met' : 'Gate not currently met')}</div><div class="review-note"><p><strong>${r.status === 'unassessed' ? 'Awaiting an explicit assessment' : `Recorded assessment: ${esc(r.status)} · ${esc(r.reviewer)} · ${fullDate(r.reviewedAt)}`}</strong></p><p>${esc(r.rationale || 'Evidence can inform a decision, but never changes a criterion status on its own.')}</p>${row?.freshness === 'changed' ? '<p>The reviewed definition or evidence has changed. The previous assessment is retained as history; explicitly re-review the current record.</p>' : row?.freshness === 'legacy-unverified' ? '<p>This older assessment has no verified snapshot. It is historical, not a current gate result.</p>' : ''}${row?.freshness === 'current' && r.status === 'met' && !row.currentMet ? '<p>The reviewed snapshot matches, but linked evidence freshness or file integrity prevents this gate counting as currently met. Inspect coverage.</p>' : ''}</div><div class="record-links">${project.evidence.filter((e) => e.criterionIds.includes(r.id)).map((e) => `<span class="link-tag">${esc(e.name)} · ${esc(e.visibility)}</span>`).join('') || '<span class="inline-count">No linked evidence yet</span>'}</div>${criterionHistory(r)}`;
  }
  if (section === 'evidence') body = `<p>${esc(r.summary)}</p><div class="record-meta"><span>Source: ${esc(r.source || 'Not provided')}</span><span>Stale after ${r.staleAfterDays} days</span></div>${links(r)}${attachments(r)}`;
  if (section === 'risks') body = `<p>${esc(r.detail)}</p><div class="review-note"><p><strong>Mitigation / next action</strong></p><p>${esc(r.mitigation || 'No mitigation recorded.')}</p></div>${links(r)}`;
  if (section === 'decisions') body = `<p>${esc(r.detail)}</p>${links(r)}`;
  if (section === 'checklist') body = `<p>${esc(r.detail || 'No additional handover instructions.')}</p>`;
  return `<article class="record-card"><div class="record-card-top"><div><h2 class="${section === 'checklist' ? 'check-title' : ''}">${section === 'checklist' ? `<button class="check-control ${r.done ? 'done' : ''}" aria-label="Mark ${esc(r.name)} ${r.done ? 'incomplete' : 'complete'}" aria-pressed="${r.done}" data-action="toggle-check" data-id="${esc(r.id)}">${r.done ? icon('check') : ''}</button>` : ''}${esc(r.name)}</h2>${meta}</div>${recordActions(section, r)}</div>${body}</article>`;
}
function criterionHistory(criterion) {
  const history = criterion.reviews || [];
  if (!history.length) return '';
  return `<details class="review-history"><summary>Review history · ${history.length}</summary>${[...history].reverse().map((review) => `<div class="history-entry"><div class="record-meta">${pill(review.status)}<span>${esc(review.reviewer)} · ${fullDate(review.date)}</span>${!review.fingerprint ? pill('legacy-unverified', 'Legacy · unverified') : ''}</div><p>${esc(review.rationale)}</p></div>`).join('')}</details>`;
}
function coverageView() {
  const cards = coverage.criteria.map((row) => {
    const criterion = project.criteria.find((item) => item.id === row.id);
    return `<article class="record-card coverage-card" data-criterion-id="${esc(row.id)}"><div class="record-card-top"><div><h2>${esc(row.name)}</h2><div class="record-meta">${pill(row.status)}${freshnessPill(row.freshness)}${pill(row.currentMet ? 'current' : 'changed', row.currentMet ? 'Current gate met' : 'Gate not currently met')}${criterion ? pill(criterion.visibility) : ''}</div></div>${btn('Review criterion', 'review-criterion', 'small', `data-id="${esc(row.id)}"`)}</div><div class="coverage-columns"><div><h3>Linked evidence · ${row.evidence.length}</h3>${row.evidence.map((evidence) => `<div class="coverage-entry"><button class="text-button" data-action="edit" data-section="evidence" data-id="${esc(evidence.id)}">${esc(evidence.name)}</button><div class="record-meta">${pill(evidence.stale ? 'stale' : 'current', evidence.stale ? 'Stale / future date' : 'Within freshness window')}<span>${esc(evidence.owner)} · ${fmtDate(evidence.collectedAt)}</span></div>${(evidence.attachments || []).map((file) => `<p class="integrity-line ${file.integrity !== 'ok' ? 'overdue' : ''}">${esc(file.name)} · ${file.integrity === 'ok' ? 'SHA-256 verified' : `Integrity: ${esc(file.integrity || 'not checked')}`}</p>`).join('')}</div>`).join('') || '<p class="coverage-empty">No linked evidence. This gate needs supporting evidence.</p>'}</div><div><h3>Linked risks · ${row.risks.length}</h3>${row.risks.map((risk) => `<div class="coverage-entry"><button class="text-button" data-action="edit" data-section="risks" data-id="${esc(risk.id)}">${esc(risk.name)}</button><div class="record-meta">${pill(risk.status)}${pill(risk.severity)}<span>${esc(risk.owner)}</span></div><p>${esc(risk.mitigation || 'No next action recorded.')}</p></div>`).join('') || '<p class="coverage-empty">No linked non-closed risks.</p>'}</div></div></article>`;
  }).join('');
  return title('FROM PROOF TO NEXT ACTION', 'Coverage & actions.', 'Trace each gate to evidence, file integrity, review freshness, and risks. Keep incomplete handover tasks visible.', btn('Refresh checks', 'refresh')) + localDecisionNotice() + gateSummary() + `<div class="record-list">${cards || empty('No gates to inspect yet.', 'Define criteria, then link evidence and risks to build a coverage view.', add('criteria'), 'criteria')}</div><section class="panel section-spacing"><div class="panel-header"><div><h2 class="panel-title">Open handover actions · ${coverage.tasks.length}</h2><p class="panel-subtitle">Overdue tasks stay visible until explicitly completed.</p></div>${add('checklist', 'Add task')}</div><div class="action-list">${coverage.tasks.map((task) => `<div class="action-row"><div><h3>${esc(task.name)}</h3><div class="record-meta"><span>${esc(task.owner)}</span><span>Due ${fullDate(task.dueDate)}</span>${task.overdue ? pill('overdue', 'Overdue') : pill('open')}${pill(task.visibility)}</div><p>${esc(task.detail)}</p></div><div class="record-actions">${btn('Edit', 'edit', 'small', `data-section="checklist" data-id="${esc(task.id)}"`)}${btn('Mark complete', 'toggle-check', 'small', `data-id="${esc(task.id)}"`)}</div></div>`).join('') || '<p class="no-results">No incomplete tasks. An empty checklist is not a handover plan.</p>'}</div></section>`;
}
function decisionView() {
  const proposals = [...(project.proposals || [])].reverse();
  const inbox = proposals.length ? `<section class="panel section-spacing" aria-label="Agent proposals"><div class="panel-header"><div><h2 class="panel-title">Agent proposals · ${proposals.length}</h2><p class="panel-subtitle">Internal suggestions, not assessments or approvals. Inspect current evidence before recording a separate human review.</p></div></div><div class="record-list">${proposals.map((proposal) => `<article class="record-card"><h3>${esc(proposal.kind === 'criterion' ? project.criteria.find(c => c.id === proposal.criterionId)?.name || 'Former criterion' : 'Pilot decision')} · ${esc(proposal.outcome)}</h3><div class="record-meta">${pill('internal')}<span>Agent: ${esc(proposal.actor)} · ${fullDate(proposal.createdAt.slice(0, 10))}</span></div><p>${esc(proposal.rationale)}</p>${proposal.conditions ? `<p>Conditions: ${esc(proposal.conditions)}</p>` : ''}<details><summary>Proposed snapshot fingerprint</summary><code>${esc(proposal.fingerprint)}</code><p>This proposal is historical if the relevant inputs changed. It never counts as a reviewed gate.</p></details>${proposal.kind === 'criterion' && project.criteria.some(c => c.id === proposal.criterionId) ? btn('Inspect criterion and evidence', 'edit', 'small', `data-section="criteria" data-id="${esc(proposal.criterionId)}"`) : ''}</article>`).join('')}</div></section>` : '';
  return humanDecisionView() + inbox;
}
function humanDecisionView() {
  const latest = decisionReviews.at(-1);
  const reviewCards = [...decisionReviews].reverse().map((review) => `<article class="record-card decision-card"><div class="record-card-top"><div><h2>${esc(review.outcome[0].toUpperCase() + review.outcome.slice(1))}</h2><div class="record-meta">${pill(review.outcome)}${freshnessPill(review.freshness)}${pill(review.visibility)}<span>${esc(review.reviewer)} · ${fullDate(review.date)}</span></div></div></div><p>${esc(review.rationale)}</p>${review.conditions ? `<div class="review-note"><p><strong>Conditions / next steps</strong></p><p>${esc(review.conditions)}</p></div>` : ''}${review.freshness !== 'current' ? '<p class="decision-warning">The pilot has changed since this decision. This is a historical decision, not a current approval.</p>' : '<p class="decision-warning">This snapshot matches the reviewed pilot. This does not mean every readiness gate is met or that anyone has authenticated the reviewer.</p>'}</article>`).join('');
  return title('MAKE THE CALL EXPLICITLY', 'Proceed, hold, or stop.', 'Record a considered local decision against a captured pilot snapshot. Review history is retained.', btn(`${icon('decisions')}Record decision review`, 'review-decision', 'primary')) + localDecisionNotice() + gateSummary() + `<div class="quality-banner">${latest ? `Latest recorded outcome: <strong>${esc(latest.outcome)}</strong> · ${esc(freshnessLabel(latest.freshness))}.` : 'No explicit pilot decision review has been recorded.'} Unmet gates and warnings remain visible even when the recorded outcome is proceed.</div><div class="record-list">${reviewCards || empty('A decision deserves a record.', 'Choose proceed, hold, or stop and explain the rationale, reviewer, date, and any conditions.', btn('Record decision review', 'review-decision', 'primary'), 'decisions')}</div><section class="section-spacing"><div class="panel-header"><div><h2 class="panel-title">Historical decision notes</h2><p class="panel-subtitle">Original notes remain editable. They are not snapshot-bound proceed / hold / stop reviews.</p></div>${add('decisions', 'Add historical note')}</div><div class="record-list">${project.decisions.map((record) => recordCard('decisions', record)).join('') || '<p class="no-results">No historical decision notes.</p>'}</div></section>`;
}
const sectionCopy = {
  criteria: ['02 / SET THE STANDARD', 'Success, made explicit.', 'Define the threshold. Examine the evidence. Record the decision.', 'No criteria, no clear finish line.', 'Add a measurable outcome with its baseline, threshold, owner, and target date. New criteria begin unassessed.'],
  evidence: ['03 / BUILD THE RECORD', 'The evidence register.', 'Keep the artifacts, context, and criterion links together.', 'Give the work a paper trail.', 'Capture a test result, review note, or observation, then attach local files. Evidence never automatically establishes success.'],
  risks: ['04 / KEEP THE QUESTIONS VISIBLE', 'Risks & blockers.', 'Make the uncertainty actionable, with an owner and a next step.', 'No risks recorded yet.', 'Capture unresolved questions and blockers. An accepted risk still appears in readiness warnings; a closed risk does not.'],
  decisions: ['05 / REMEMBER THE WHY', 'The decision log.', 'A durable record of what was agreed, when, and by whom.', 'Make the next decision a clear one.', 'Write down the decision and the reasoning behind it. Link it to the outcomes it affects.'],
  checklist: ['06 / LEAVE IT IN GOOD HANDS', 'The handover checklist.', 'From ownership and runbooks to the final review. Close the loop.', 'Plan what happens after the pilot.', 'Add owned, dated handover tasks. A completed checklist is useful, but does not mark criteria as successful.']
};
function records(section) {
  const [eyebrow, heading, desc, emptyHeading, emptyDesc] = sectionCopy[section];
  const headingHtml = title(eyebrow, heading, desc, add(section));
  if (!project[section].length) return headingHtml + empty(emptyHeading, emptyDesc, add(section), section);
  const statusOptions = section === 'criteria' ? ['unassessed', 'met', 'unmet', 'blocked'] : section === 'risks' ? ['open', 'mitigated', 'accepted', 'closed'] : section === 'checklist' ? ['complete', 'open'] : section === 'evidence' ? ['fresh', 'stale'] : [];
  return headingHtml + (section === 'criteria' ? '<div class="quality-banner"><strong>Definition edits are not reviews.</strong> Use Review criterion to record met, unmet, or blocked with a reviewer, rationale, and date. Edits preserve prior reviews; changed or legacy-unverified assessments do not count as current success.</div>' : '') + `<div class="toolbar"><div class="filter-group"><input class="search-input" id="record-search" type="search" placeholder="Search ${esc(routes.find(([key]) => key === section)[1].toLowerCase())}…" aria-label="Search records" value="${esc(filter.query)}"><select class="filter-select" id="visibility-filter" aria-label="Filter by visibility">${[['all', 'All visibility'], ['customer', 'Customer-visible'], ['internal', 'Internal only']].map(([value, label]) => `<option value="${value}" ${filter.visibility === value ? 'selected' : ''}>${label}</option>`).join('')}</select>${statusOptions.length ? `<select class="filter-select" id="status-filter" aria-label="Filter by status"><option value="all">All statuses</option>${statusOptions.map((value) => `<option ${filter.status === value ? 'selected' : ''} value="${value}">${value[0].toUpperCase() + value.slice(1)}</option>`).join('')}</select>` : ''}</div><span class="count-summary">${project[section].length} record${project[section].length === 1 ? '' : 's'} · ${project[section].filter((r) => r.visibility === 'customer').length} customer-visible</span></div><div class="record-list" id="record-list">${filteredRecords(section)}</div>`;
}
function filteredRecords(section) {
  const items = project[section].filter((r) => {
    const status = section === 'checklist' ? (r.done ? 'complete' : 'open') : section === 'evidence' ? (isStale(r) ? 'stale' : 'fresh') : r.status;
    return (filter.visibility === 'all' || r.visibility === filter.visibility) && (filter.status === 'all' || status === filter.status) && `${r.name} ${r.owner} ${r.summary || r.detail || r.metric || ''}`.toLowerCase().includes(filter.query.toLowerCase());
  });
  return items.map((r) => recordCard(section, r)).join('') || '<div class="panel no-results">No records match these filters. Try a different search or visibility.</div>';
}
function handover() {
  const internalRecords = ['criteria', 'evidence', 'risks', 'decisions', 'checklist'].reduce((total, section) => total + project[section].filter((r) => r.visibility === 'internal').length, 0) + (project.decisionReviews || []).filter((review) => review.visibility === 'internal').length;
  const customerEvidence = new Set(project.evidence.filter((e) => e.visibility === 'customer').map((e) => e.id)); const sharedFiles = project.attachments.filter((a) => a.visibility === 'customer' && customerEvidence.has(a.evidenceId)).length;
  return title('07 / MAKE THE HANDOVER COUNT', 'A record worth handing over.', 'Preview the customer view. Resolve the gaps. Share only what you mean to.', btn(`Open printable preview ↗`, 'open-preview')) + localDecisionNotice() + gateSummary() + `<div class="preview-intro"><h2>${icon('shield')} Customer-safe by explicit visibility</h2><p>${internalRecords} internal records excluded. ${project.attachments.length - sharedFiles} attachments excluded. Internal charter notes and links to internal criteria are always removed. An attachment must be customer-visible <em>and</em> belong to customer-visible evidence to be included.</p><p>Visibility is not automatic text redaction. Customer-facing names, summaries, sources, reviewer names, and file contents are shared as written. Review this exact preview before distribution. Private workspace warnings below are not part of the customer export.</p></div><div class="export-grid"><article class="export-card">${icon('handover')}<h2>Customer handover</h2><p>A self-contained, escaped HTML document. Includes only customer-visible attachments as offline downloads. Print it to PDF in your browser.</p>${btn(`${icon('download')}Export customer HTML`, 'export-html', 'primary')}</article><article class="export-card">${icon('evidence')}<h2>Evidence manifest</h2><p>Customer-visible criteria, evidence, attachment metadata, and SHA-256 digests. A machine-readable index, not a full backup.</p>${btn(`${icon('download')}Export manifest`, 'export-manifest')}</article><article class="export-card">${icon('charter')}<h2>Deckforge handoff</h2><p>Customer-visible pilot content only, ready to import into Deckforge. Review the generated deck before sharing; internal records, hidden snapshots, and private file contents stay excluded.</p><a class="button" id="deckforge-export" href="${esc(projectUrl('/api/export/deckforge'))}" download="proofpack-deckforge.json" data-action="export-deckforge">${icon('download')}Export to Deckforge</a></article><article class="export-card">${icon('lock')}<h2>Full private backup</h2><p>All records, internal notes, and attachment bytes. Validated and roundtrippable. This is a private recovery file, not a customer deliverable.</p>${btn(`${icon('download')}Private backup…`, 'backup')}</article></div><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Private workspace readiness ${pill('internal', `${readiness.warnings.length} notes`)}</h2><p class="panel-subtitle">All records, including internal ones. These checks are not customer-facing.</p></div>${btn('Refresh checks', 'refresh', 'small')}</div><ul class="warning-list">${readiness.warnings.map((w) => `<li><span class="warning-symbol" aria-hidden="true">!</span><span>${esc(w.message)}</span></li>`).join('') || '<li>Automated checks are clear. A human handover decision is still required.</li>'}</ul></section><div class="section-spacing"><div class="panel-header"><div><h2 class="panel-title">The actual customer preview</h2><p class="panel-subtitle">Same redacted content as the downloaded HTML. No internal records or internal-only warning counts.</p></div>${btn('Open ↗', 'open-preview', 'small')}</div><iframe class="preview-frame" title="Customer-visible handover preview" src="${esc(projectUrl('/handover'))}" sandbox="allow-same-origin allow-downloads"></iframe></div>`;
}
function help() {
  return title('A LITTLE GUIDANCE', 'Keep the work clear.', 'How Proofpack stores your data, protects the boundary, and gets out of the way.') + `<div class="help-layout"><article class="panel help-article"><h2>A local workspace, on purpose.</h2><p>Proofpack is a local multi-pilot evidence and handover workspace. The pilot library creates isolated pilots, switches only this browser tab, and archives or unarchives without deleting records. The URL identifies the selected pilot; other open tabs keep their own selection. Archived pilots are read-only, including for edits in another tab. No accounts, telemetry, external fonts, remote calls or automatic AI decisions. It listens only on <code>127.0.0.1:4313</code>. It is designed for a trusted single-user machine, not public hosting.</p><h3>Start, stop, and test</h3><pre><code>cd proofpack\nnpm ci\nnode agent/cli.mjs commands\nnode agent/cli.mjs init --workspace /absolute/path\nnode agent/cli.mjs setup --workspace /absolute/path\nnode agent/cli.mjs ui --workspace /absolute/path\n# Legacy default UI:\nnpm start\n# Open http://127.0.0.1:4313\n# Stop with Ctrl+C\nnpm start -- --help\nnpm test</code></pre><p>Requires Node 23 or newer. Use the exact numeric address, not <code>localhost</code>; strict Host and Origin checks reject other hosts. Do not expose the port or reverse-proxy the service. CLI and UI operations share workspace locks and revision checks.</p><h3>1. Define and review success</h3><p>Complete the charter, then add criteria with a metric, baseline, threshold, owner, and target date. Status begins <strong>unassessed</strong>. Use the separate <strong>Review criterion</strong> action to record <strong>met</strong>, <strong>unmet</strong>, or <strong>blocked</strong> with a reviewer, written rationale, and date. Editing the definition never overwrites an assessment. Reviews retain a fingerprint and snapshot of the reviewed definition and linked evidence. A <strong>current</strong> review matches those inputs; <strong>changed</strong> needs re-review; <strong>legacy-unverified</strong> is an older assessment with no verified snapshot. Prior assessments remain visible as history. Uploading, relinking, or editing evidence cannot create a review. Only current met reviews with supporting, timely evidence and valid files count as currently met.</p><h3>2. Evidence and attachments</h3><p>Evidence has its own summary, source, owner, collection date, freshness window (1–3650 days), and criterion links. Evidence is stale when its age is greater than that window. Future collection dates, unlinked evidence, missing files, and changed file hashes produce warnings.</p><ul><li>Upload files from the evidence card. New records and files default to <strong>internal</strong>. Each file must be 1 byte–8 MiB. Up to 100 active attachments and 100 retained historical attachments, with 40 MiB total bytes including retained history, per pilot.</li><li>Names are plain filenames, max 160 characters; paths, slashes, reserved filename characters, control characters, and trailing spaces/dots are rejected. No arbitrary filesystem paths are accepted.</li><li>Files are stored by SHA-256 digest, with original name, media type, size, upload time, visibility, and evidence link in metadata. Downloads verify size and hash, and are always attachments—not inline executable previews.</li><li>Proofpack does not scan for malware or secrets. Treat uploaded files as untrusted. Do not open an attachment you do not trust.</li><li>Deleting evidence removes active attachment metadata, but attachments referenced by reviews are retained for history and private backups. Reviewed criteria cannot be deleted, so their history is not lost. Deleting an unreviewed criterion removes its inbound links. Unreferenced file blobs may be cleaned after committed saves; keep a private backup before destructive actions.</li></ul><h3>3. Visibility and redaction</h3><p>Charter customer, title, objective, owners, and dates are customer-facing; only <strong>internal notes</strong> are private. New records are internal. Mark individual records and attachments customer-visible only after review. A shared file under internal evidence stays excluded. Links to internal criteria are removed. A shared evidence record remains shareable even if all of its criterion links are internal; the links are stripped and the preview warns that it is unlinked.</p><p>Customer HTML, shared attachment bytes, evidence manifest, Deckforge handoff, and customer-view readiness checks all use the same visibility boundary. Internal records, internal-only counts and attachment metadata, internal charter notes, and private review snapshots are excluded. Customer-visible records may include their own identifiers, attachment metadata, and review details. Review freshness in customer exports is based on customer-visible inputs, not hidden records. <strong>Free-text fields and file contents are not semantically redacted.</strong> Do not paste private facts into shared fields. The preview is the actual rendered export; inspect it before sharing.</p><h3>4. Customer export and PDF</h3><p>Customer handover → <strong>Export customer HTML</strong> downloads a self-contained offline document, including shared attachment downloads. <strong>Open printable preview</strong> opens the same view; use your browser’s <strong>Print → Save as PDF</strong>. PDF preserves the visible report and digests, not attachment bytes. Use HTML plus a manifest when the customer needs files. The manifest is metadata-only and cannot be imported as a backup. <strong>Export to Deckforge</strong> downloads a customer-only handoff JSON for import into Deckforge; it does not contact Deckforge or publish anything. Review the imported deck before distributing it.</p><h3>5. Private backup and import</h3><p>Choose <strong>Private backup…</strong> and acknowledge that it includes all internal records and file contents. The JSON envelope uses <code>format: proofpack-backup</code>, version 1, the complete project, and canonical base64 <code>attachmentData</code> for every attachment. Missing, unsafe, or corrupt files block full backup rather than silently producing an incomplete recovery file.</p><p>Choose <strong>Import full backup…</strong>, select a JSON file, and confirm replacement. Take a private backup first: import replaces the active pilot, not merges. Import validates every field, ID, enum, date, review, link, filename, size, and SHA-256. Unknown fields, malformed JSON/base64, duplicates, broken references, unsupported versions, and digest mismatches are rejected before replacing the project. Backup file limit is 64 MiB; attachment and record limits still apply. Maximum 500 records per section; project text and metadata are limited to 4 MiB so complete exports remain importable.</p><h3>6. Persistence, conflicts, and recovery</h3><p>The local data directory holds the pilot library, a project record for each pilot, and attachment blobs stored by SHA-256. The original pilot remains available when the library is initialized; new pilots use isolated stores. Never move or edit storage files while the server is running. Saves use a temporary file, file sync, and atomic rename. Attachment bytes are written before metadata; a failed import leaves the current project intact. Use the export function instead of copying data while the server is running. Criterion and decision reviews preserve their reviewed snapshots and history. Generic record edits have no undo; keep private backups of each pilot. A full backup is for one pilot and does not include the library catalog.</p><p>Concurrent tab edits use revision checks. If a save conflicts, your draft stays open; copy it somewhere safe, cancel, refresh the workspace, and reapply. Agent-first CLI and UI commands coordinate through per-operation .agent.lock files. The CLI uses <code>data/server.lock</code>; if a crash leaves it behind, confirm no Proofpack process is running before manually removing only that lock and restarting.</p><p>If saved JSON is corrupt, the server refuses to overwrite it. Stop the server and preserve a copy of the entire data directory before attempting recovery. Do not remove library entries or guess which pilot files to replace; restore a verified backup into the intended pilot only after checking the affected store. Missing or changed attachments show warnings and cannot download; remove their metadata and upload the correct file, or restore a verified backup. Stored data and backups are not encrypted. Protect your device and private export files.</p><h3>7. Coverage and explicit decision review</h3><p><strong>Coverage &amp; actions</strong> traces each criterion to its evidence, file-integrity results, open risks, and current-review state, followed by incomplete and overdue handover tasks. Readiness also flags incomplete charter fields, stale/future evidence, expired targets, and missing checklist items. Historical met counts are displayed separately from current met gates.</p><p><strong>Decision review</strong> records an explicit proceed, hold, or stop outcome, rationale, reviewer, date, conditions, and visibility. It preserves a snapshot of the pilot. Later changes can make that decision outdated; recording proceed never hides unmet gates. The original decision notes remain historical notes, separate from decision reviews. Reviewer names are self-entered: <strong>a local decision record is not authenticated approval or customer sign-off.</strong> Customer readiness only checks customer-visible data; a clear customer preview does not clear internal problems.</p><h3>Fictional demo</h3><p>The sample is a synthetic pilot for “Alder & Finch,” explicitly labeled fictional throughout. All names, results, and artifacts are made up. Loading it replaces the current workspace after confirmation. Use <strong>Create pilot</strong> in the library to start your own work without replacing the sample. The destructive <strong>Start a blank pilot…</strong> action clears only the selected pilot after confirmation.</p></article><div class="side-stack"><section class="readiness-card"><span class="section-kicker">YOUR LOCAL DATA</span><h3>Portable. Not public.</h3><p>${project.criteria.length} criteria · ${project.evidence.length} evidence records<br>${project.attachments.length} active · ${(project.attachmentHistory || []).length} retained historical attachments · ${bytes([...project.attachments, ...(project.attachmentHistory || [])].reduce((sum, a) => sum + a.size, 0))} / 40 MiB<br>Saved revision ${project.revision}</p>${btn(`${icon('download')}Private backup…`, 'backup')}${btn(`${icon('upload')}Import full backup…`, 'import')}</section><section class="danger-zone"><h3>Replace this workspace</h3><p>These actions replace the current pilot. Export a full private backup first if you need to keep it. Nothing is sent to a remote service.</p>${btn('Load fictional sample…', 'demo')}${btn('Start a blank pilot…', 'reset', 'danger')}</section><div class="note-strip">${icon('lock')}<span><strong>Trust boundary</strong><br>Loopback does not mean authentication. Anyone with access to this machine and browser session may access this workspace. Do not use a shared untrusted device.</span></div></div></div>`;
}

function input(name, label, value = '', options = {}) {
  const { type = 'text', required = false, full = false, hint = '', values, min, max, maxLength = 4000 } = options;
  const attrs = `name="${name}" id="field-${name}" ${required ? 'required' : ''} ${hint ? `aria-describedby="hint-${name}"` : ''}`;
  let control;
  if (type === 'textarea') control = `<textarea ${attrs} maxlength="${maxLength}" rows="3">${esc(value)}</textarea>`;
  else if (type === 'select') control = `<select ${attrs}>${values.map((item) => { const [key, text] = Array.isArray(item) ? item : [item, item[0].toUpperCase() + item.slice(1)]; return `<option value="${esc(key)}" ${key === value ? 'selected' : ''}>${esc(text)}</option>`; }).join('')}</select>`;
  else control = `<input ${attrs} type="${type}" value="${esc(value)}" ${['text', 'url'].includes(type) ? `maxlength="${maxLength}"` : ''} ${min !== undefined ? `min="${min}"` : ''} ${max !== undefined ? `max="${max}"` : ''}>`;
  return `<div class="field ${full ? 'full' : ''}"><label for="field-${name}">${esc(label)}${required ? ' *' : ''}</label>${control}${hint ? `<small id="hint-${name}">${esc(hint)}</small>` : ''}</div>`;
}
function visibilityField(value = 'internal') { return input('visibility', 'Visibility', value, { type: 'select', values: [['internal', 'Internal — excluded from customer export'], ['customer', 'Customer-visible — included in customer export']], full: true, hint: 'Customer-visible free text and file contents are shared as written. Review for private information.' }); }
function linkField(ids = []) { return `<div class="field full"><span class="field-label" id="criterion-links-label">Linked success criteria</span><div class="link-checks" role="group" aria-labelledby="criterion-links-label">${project.criteria.map((c) => `<label class="link-check"><input type="checkbox" name="criterionIds" value="${esc(c.id)}" ${ids.includes(c.id) ? 'checked' : ''}>${esc(c.name)} · ${esc(c.visibility)}</label>`).join('') || '<span class="inline-count">No criteria yet. Save this record, then add a criterion and link it.</span>'}</div><small>Internal criterion links are stripped from customer exports.</small></div>`; }
